-- FICTIONAL, disposable fixture only. This is not the finance production schema.
CREATE SCHEMA finance_cutover_fixture;
CREATE TABLE finance_cutover_fixture.accounts (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 branch_id BIGINT NOT NULL DEFAULT 1 REFERENCES public.branches(id), label TEXT NOT NULL,
 opening_amount NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (opening_amount>=0),
 opening_date DATE NOT NULL DEFAULT DATE '2020-01-01',
 counted_by BIGINT NOT NULL DEFAULT 1 REFERENCES public.users(id),
 counted BOOLEAN NOT NULL DEFAULT TRUE CHECK(counted)
);
CREATE TABLE finance_cutover_fixture.checkpoints (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, account_id BIGINT NOT NULL REFERENCES finance_cutover_fixture.accounts(id),
 kind VARCHAR(8) NOT NULL CHECK(kind IN ('OPENING','COUNT')),counted_on DATE NOT NULL,
 observed_amount NUMERIC(14,2) NOT NULL CHECK(observed_amount>=0), confirmed_by BIGINT NOT NULL REFERENCES public.users(id)
);
CREATE UNIQUE INDEX finance_cutover_fixture_one_opening ON finance_cutover_fixture.checkpoints(account_id) WHERE kind='OPENING';
CREATE TABLE finance_cutover_fixture.expenses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, label TEXT NOT NULL);
CREATE TABLE finance_cutover_fixture.payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, expense_id BIGINT NOT NULL REFERENCES finance_cutover_fixture.expenses(id));
CREATE TABLE finance_cutover_fixture.movements (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 collection_id BIGINT UNIQUE REFERENCES public.commerce_collections(id),refund_id BIGINT UNIQUE REFERENCES public.commerce_refunds(id),
 account_id BIGINT NOT NULL REFERENCES finance_cutover_fixture.accounts(id),checkpoint_id BIGINT NOT NULL REFERENCES finance_cutover_fixture.checkpoints(id),
 amount NUMERIC(14,2) NOT NULL CHECK(amount>0),direction VARCHAR(3) NOT NULL CHECK(direction IN ('IN','OUT')),
 after_checkpoint BOOLEAN NOT NULL CHECK(after_checkpoint),
 CHECK ((collection_id IS NOT NULL AND refund_id IS NULL AND direction='IN') OR
        (collection_id IS NULL AND refund_id IS NOT NULL AND direction='OUT'))
);
CREATE TABLE finance_cutover_fixture.historical (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 collection_id BIGINT UNIQUE REFERENCES public.commerce_collections(id),refund_id BIGINT UNIQUE REFERENCES public.commerce_refunds(id),
 account_id BIGINT NOT NULL REFERENCES finance_cutover_fixture.accounts(id),checkpoint_id BIGINT NOT NULL REFERENCES finance_cutover_fixture.checkpoints(id),
 amount NUMERIC(14,2) NOT NULL CHECK(amount>0),actual_date DATE NOT NULL,
 included_in_checkpoint BOOLEAN NOT NULL CHECK(included_in_checkpoint),same_day_before BOOLEAN NOT NULL DEFAULT FALSE,
 handler TEXT NOT NULL CHECK(length(btrim(handler))>0),reason TEXT NOT NULL CHECK(length(btrim(reason))>0),
 confirmed_by BIGINT NOT NULL REFERENCES public.users(id),
 CHECK ((collection_id IS NOT NULL AND refund_id IS NULL) OR (collection_id IS NULL AND refund_id IS NOT NULL))
);
CREATE TABLE finance_cutover_fixture.requests (id UUID PRIMARY KEY);
CREATE TABLE finance_cutover_fixture.audit_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, note TEXT NOT NULL);
